import { Badge, Nav, NavGroup, NavItem, NavList, PageSidebar, PageSidebarBody } from '@patternfly/react-core';
import { useEffect, useState } from 'react';
import type { NavigationDomain } from '../data/client';
import { usePrincipal } from '../principal/PrincipalProvider';
import { routeHref, type Route } from '../routing';

/**
 * The sidebar (design system spec 4.1): To do, then the object world of the person's work, generated by
 * the gateway from their roles' work domains (platform spec 5.1).
 */
export function AppSidebar({ isOpen, route, onNavigate }: { isOpen: boolean; route: Route; onNavigate: () => void }) {
  const { client, principal } = usePrincipal();
  const [domains, setDomains] = useState<NavigationDomain[]>([]);

  useEffect(() => {
    let cancelled = false;
    client.navigation(principal).then((d) => !cancelled && setDomains(d));
    return () => {
      cancelled = true;
    };
  }, [client, principal]);

  return (
    <PageSidebar isSidebarOpen={isOpen}>
      <PageSidebarBody>
        <Nav aria-label="Main navigation" onSelect={onNavigate}>
          <NavList>
            <NavItem to={routeHref({ name: 'todo' })} isActive={route.name === 'todo'}>
              To do
            </NavItem>
          </NavList>
          {domains.map((domain) => (
            <NavGroup key={domain.domain} title={domain.label}>
              {domain.types.map((t) => (
                <NavItem key={t.type} to={routeHref({ name: 'type', type: t.type })} isActive={route.name === 'type' && route.type === t.type}>
                  {t.pluralLabel} <Badge isRead screenReaderText={t.count === 1 ? 'object' : 'objects'}>{t.count}</Badge>
                </NavItem>
              ))}
            </NavGroup>
          ))}
        </Nav>
      </PageSidebarBody>
    </PageSidebar>
  );
}
